files.repair-check.ps1:
$expected = 'enabled=true'
if (-not (Test-Path -LiteralPath './config.txt')) { Write-Output 'CONFIG_MISSING'; exit 9 }
$value = (Get-Content -LiteralPath './config.txt' -Raw).Trim()
if ($value -ne $expected) { Write-Output 'CAL_REPAIR_FAIL'; exit 7 }
Write-Output 'CAL_REPAIR_OK'
exit 0
